if (!context.panel.data?.series?.length) return {};


const groupBy = 'Category1'
const labels = context.panel.data.series[0].fields.find(f => f.name === groupBy).values;
const values = context.panel.data.series[0].fields.find(f => f.name === 'Count_ObjNr').values;
const raw = labels.map((l, i) => ({ name: l ?? '(none)', value: values[i] ?? 0 })).sort((a, b) => b.value - a.value);

const TOP = 12;
const top = raw.slice(0, TOP);
const otherSum = raw.slice(TOP).reduce((s, d) => s + d.value, 0);
if (otherSum > 0) top.push({ name: 'Other', value: otherSum });
const total = top.reduce((s, d) => s + d.value, 0);

return {
  backgroundColor: 'transparent',
  tooltip: {
    trigger: 'item',
    backgroundColor: '#051C2D',
    borderColor: '#FFA314',
    borderWidth: 1,
    textStyle: { color: '#F5F5F5', fontSize: 13 },
    formatter: p => `<b>${p.name}</b><br/>Count: <b>${p.value}</b><br/>Share: <b>${p.percent}%</b>`
  },
  legend: {
    type: 'scroll',
    orient: 'vertical',
    right: '2%',
    top: 'middle',
    width: 160,
    itemWidth: 10,
    itemHeight: 10,
    itemGap: 8,
    textStyle: { color: '#F5F5F5', fontSize: 11 },
    pageTextStyle: { color: '#F5F5F5' },
    pageIconColor: '#FFA314',
    pageIconInactiveColor: '#bfbfbf',
    formatter: name => {
      const d = top.find(x => x.name === name);
      const pct = d ? ((d.value / total) * 100).toFixed(1) : 0;
      const label = name.length > 18 ? name.slice(0, 17) + '…' : name;
      return `${label}  ${pct}%`;
    }
  },
  series: [{
    type: 'pie',
    radius: ['40%', '80%'],
    center: ['42%', '50%'],
    avoidLabelOverlap: true,
    itemStyle: { borderRadius: 5, borderColor: 'rgba(0,0,0,0.3)', borderWidth: 2 },
    label: { show: true, position: 'outside', color: '#F5F5F5', fontSize: 11, formatter: p => p.percent > 4 ? `${p.percent}%` : '' },
    labelLine: { length: 8, length2: 12, lineStyle: { color: '#bfbfbf' } },
    emphasis: {
      scale: true,
      scaleSize: 6,
      itemStyle: { shadowBlur: 20, shadowOffsetX: 0, shadowColor: 'rgba(5,28,45,0.5)' }
    },
    data: top
  }]
};

