if (!context.panel.data?.series?.length) return {};
const groupBy = 'Category1';
const groupBy2 = 'Category2';
const fields = context.panel.data.series[0].fields;
const cat1 = fields.find(f => f.name === groupBy).values;
const cat2 = fields.find(f => f.name === groupBy2).values;
const counts = fields.find(f => f.name === 'Count_ObjNr').values;

const lookup = {};
cat2.forEach((c2, i) => {
  if (!lookup[c2]) lookup[c2] = {};
  lookup[c2][cat1[i]] = (lookup[c2][cat1[i]] ?? 0) + counts[i];
});

const cat2Values = [...new Set(cat2)]
  .filter(Boolean)
  .sort((a, b) => {
    const sumA = Object.values(lookup[a] ?? {}).reduce((s, v) => s + v, 0);
    const sumB = Object.values(lookup[b] ?? {}).reduce((s, v) => s + v, 0);
    return sumB - sumA;
  })
  .slice(0, 20);

// Sort cat1 by total count descending — largest total = first series = bottom of stack
const cat1Values = [...new Set(cat1)]
  .filter(Boolean)
  .sort((a, b) => {
    const sumA = cat2Values.reduce((s, c2) => s + (lookup[c2]?.[a] ?? 0), 0);
    const sumB = cat2Values.reduce((s, c2) => s + (lookup[c2]?.[b] ?? 0), 0);
    return sumB - sumA;
  });

return {
  backgroundColor: 'transparent',
  legend: {
    type: 'scroll',
    orient: 'vertical',
    right: '1%',
    top: 'middle',
    width: 160,
    itemWidth: 10,
    itemHeight: 10,
    itemGap: 6,
    textStyle: { color: '#F5F5F5', fontSize: 11 },
    pageTextStyle: { color: '#F5F5F5' },
    pageIconColor: '#FFA314',
    pageIconInactiveColor: '#bfbfbf',
    data: cat1Values.slice(0, 20),
  },
  grid: { left: '4%', right: '180px', top: '6%', bottom: '8%', containLabel: true },
  xAxis: {
    type: 'category',
    data: cat2Values,
    axisLabel: {
      interval :0,
      color: '#F5F5F5',
      fontSize: 11, rotate: 90,
      formatter: name => name.length > 10 ? name.slice(0, 11) + '…' : name
    }
  },
  yAxis: {
    type: 'value',
    axisLabel: { color: '#F5F5F5' },
    splitLine: { lineStyle: { color: 'rgba(255,255,255,0.1)' } }
  },
  tooltip: {
    trigger: 'axis',
    axisPointer: { type: 'shadow' },
    backgroundColor: '#051C2D',
    borderColor: '#FFA314',
    borderWidth: 1,
    textStyle: { color: '#F5F5F5', fontSize: 12 },
    formatter: params => {
      const nonZero = params.filter(p => p.value > 0);
      if (!nonZero.length) return '';
      const rows = nonZero.map(p => `${p.marker} ${p.seriesName}: <b>${p.value}</b>`).join('<br/>');
      return `<b>${params[0].name}</b><br/>${rows}`;
    }
  },
  series: cat1Values.map(c1 => ({
    name: c1 ?? '(none)',
    type: 'bar',
    stack: 'total',
    emphasis: { focus: 'series' },
    label: { show: false },
    data: cat2Values.map(c2 => lookup[c2]?.[c1] ?? 0)
  }))
};
